use crate::ipc::{run_blocking, IpcError};
use crate::worktree::{run_git, WorkspaceRegistry, WorktreeError};
use serde::{Deserialize, Serialize};
use std::path::{Path, PathBuf};
use tauri::State;

/// Workspace ID that shipped as a hard-coded alias for the startup repository.
/// It is no longer registered; persisted clients that still send it are mapped
/// onto the canonical derived ID instead (see [`resolve_workspace_id`]).
pub const LEGACY_DEFAULT_WORKSPACE_ID: &str = "default";

/// Fallback ID for a root whose folder name carries no usable characters.
const FALLBACK_WORKSPACE_ID: &str = "project";

/// Derives the canonical workspace ID for a repository root from its folder
/// name, restricted to characters `WorkspaceRegistry::validate_workspace_id`
/// accepts (no separators, whitespace, control characters, or leading `-`).
pub fn derive_workspace_id(repo_root: &Path) -> String {
    repo_root
        .file_name()
        .and_then(|name| name.to_str())
        .map(|name| {
            let slug: String = name
                .chars()
                .map(|ch| if ch.is_alphanumeric() || ch == '_' || ch == '-' { ch } else { '-' })
                .collect();
            let trimmed = slug.trim_matches('-');
            if trimmed.is_empty() {
                FALLBACK_WORKSPACE_ID.to_string()
            } else {
                trimmed.to_string()
            }
        })
        .unwrap_or_else(|| FALLBACK_WORKSPACE_ID.to_string())
}

/// Maps a requested workspace ID onto the ID actually held by the registry.
///
/// The only rewrite is the legacy `default` alias: when a persisted client asks
/// for `default` and no such workspace is registered, the request resolves to
/// the canonical ID derived from the startup root. No alias is created, so the
/// registry keeps exactly one entry per repository root.
pub fn resolve_workspace_id(registry: &WorkspaceRegistry, requested: &str) -> String {
    if requested != LEGACY_DEFAULT_WORKSPACE_ID || registry.contains(LEGACY_DEFAULT_WORKSPACE_ID) {
        return requested.to_string();
    }
    match canonical_startup_root() {
        Some(repo_root) => {
            let canonical = derive_workspace_id(&repo_root);
            if registry.contains(&canonical) {
                canonical
            } else {
                requested.to_string()
            }
        }
        None => requested.to_string(),
    }
}

fn canonical_startup_root() -> Option<PathBuf> {
    let cwd = std::env::current_dir().ok()?;
    Some(cwd.canonicalize().unwrap_or(cwd))
}

/// Registers (idempotently) and returns the single canonical project for the
/// startup repository root.
pub fn initial_project(registry: &WorkspaceRegistry) -> Result<RegisteredProject, IpcError> {
    let repo_root = canonical_startup_root().ok_or_else(|| {
        IpcError::from(WorktreeError::InvalidPath {
            path: PathBuf::from("."),
            reason: "the startup working directory is unavailable".into(),
        })
    })?;
    let workspace_id = derive_workspace_id(&repo_root);
    registry
        .register(&workspace_id, &repo_root)
        .map_err(IpcError::from)?;
    let repo_root = registry.repo_root(&workspace_id).map_err(IpcError::from)?;
    Ok(RegisteredProject {
        workspace_id,
        repo_root,
    })
}

